window.__ACL__.fromEuler = function fromEuler(roll, pitch, yaw) {
  const cr = Math.cos(roll * 0.5);
  const sr = Math.sin(roll * 0.5);
  const cp = Math.cos(pitch * 0.5);
  const sp = Math.sin(pitch * 0.5);
  const cy = Math.cos(yaw * 0.5);
  const sy = Math.sin(yaw * 0.5);

  return normalizeQuaternion([
    cr * cp * cy + sr * sp * sy,
    sr * cp * cy - cr * sp * sy,
    cr * sp * cy + sr * cp * sy,
    cr * cp * sy - sr * sp * cy,
  ]);
}

window.__ACL__.toEuler = function toEuler(q) {
  const [w, x, y, z] = normalizeQuaternion(q);

  const sinrCosp = 2 * (w * x + y * z);
  const cosrCosp = 1 - 2 * (x * x + y * y);
  const roll = Math.atan2(sinrCosp, cosrCosp);

  const sinp = 2 * (w * y - z * x);
  const pitch = Math.abs(sinp) >= 1 ? Math.sign(sinp) * (Math.PI / 2) : Math.asin(sinp);

  const sinyCosp = 2 * (w * z + x * y);
  const cosyCosp = 1 - 2 * (y * y + z * z);
  const yaw = Math.atan2(sinyCosp, cosyCosp);

  return [roll, pitch, yaw];
}

window.__ACL__.smoothQuaternionToward = function smoothQuaternionToward(q, toward, rate) {
  const mixed = q.map((value, index) => value * (1 - rate) + toward[index] * rate);
  return normalizeQuaternion(mixed);
}

window.__ACL__.axisAngle = function axisAngle(axis, angle) {
  const axisNorm = magnitude(axis) || 1;
  const normalized = axis.map((value) => value / axisNorm);
  const half = angle * 0.5;
  const s = Math.sin(half);
  return normalizeQuaternion([Math.cos(half), normalized[0] * s, normalized[1] * s, normalized[2] * s]);
}

// ----- control.js -----
const { addMatrices, cloneMatrix, diag, identity, inverse, mulMatrices, mulMatrixVector, scaleMatrix, subMatrices, subVectors } = window.__ACL__;
window.__ACL__.buildHoverModel = function buildHoverModel(params, dt) {
  const { gravity, mass, inertia, linearDamping, angularDamping } = params;
  const [ixx, iyy, izz] = inertia;

  const A = Array.from({ length: 12 }, () => Array(12).fill(0));
  const B = Array.from({ length: 12 }, () => Array(4).fill(0));

  A[0][3] = 1;
  A[1][4] = 1;
  A[2][5] = 1;

  A[3][3] = -linearDamping;
  A[4][4] = -linearDamping;
  A[5][5] = -linearDamping;
  A[3][7] = gravity;
  A[4][6] = -gravity;

  A[6][9] = 1;
  A[7][10] = 1;
  A[8][11] = 1;

  A[9][9] = -angularDamping;
  A[10][10] = -angularDamping;
  A[11][11] = -angularDamping;

  B[5][0] = 1 / mass;
  B[9][1] = 1 / ixx;
  B[10][2] = 1 / iyy;
  B[11][3] = 1 / izz;

  const Ad = addMatrices(identity(12), scaleMatrix(A, dt));
  const Bd = scaleMatrix(B, dt);
  return { A, B, Ad, Bd };
}

window.__ACL__.buildWeights = function buildWeights(stateScale, effortScale) {
  const q = diag([
    8.5 * stateScale,
    8.5 * stateScale,
    10.0 * stateScale,
    3.1 * stateScale,
    3.1 * stateScale,
    4.1 * stateScale,
    6.2 * stateScale,
    6.2 * stateScale,
    2.8 * stateScale,
    1.4 * stateScale,
    1.4 * stateScale,
    0.9 * stateScale,
  ]);

  const r = diag([
    0.42 * effortScale,
    0.18 * effortScale,
    0.18 * effortScale,
    0.26 * effortScale,
  ]);

  return { q, r };
}

window.__ACL__.solveDiscreteLQR = function solveDiscreteLQR(ad, bd, q, r, iterations = 140) {
  let p = cloneMatrix(q);
  const at = ad[0].map((_, col) => ad.map((row) => row[col]));
  const bt = bd[0].map((_, col) => bd.map((row) => row[col]));

  for (let i = 0; i < iterations; i += 1) {
    const btpb = mulMatrices(bt, mulMatrices(p, bd));
    const gainTerm = inverse(addMatrices(r, btpb));
    const atpa = mulMatrices(at, mulMatrices(p, ad));
    const atpb = mulMatrices(at, mulMatrices(p, bd));
    const reduction = mulMatrices(atpb, mulMatrices(gainTerm, mulMatrices(bt, mulMatrices(p, ad))));
    p = addMatrices(q, subMatrices(atpa, reduction));
  }

  const k = mulMatrices(inverse(addMatrices(r, mulMatrices(bt, mulMatrices(p, bd)))), mulMatrices(bt, mulMatrices(p, ad)));
  return k;
}

window.__ACL__.buildMeasurementModel = function buildMeasurementModel() {
  const h = Array.from({ length: 9 }, () => Array(12).fill(0));
  h[0][0] = 1;
  h[1][1] = 1;
  h[2][2] = 1;
  h[3][6] = 1;
  h[4][7] = 1;
  h[5][8] = 1;
  h[6][9] = 1;
  h[7][10] = 1;
  h[8][11] = 1;
  return h;
}

window.__ACL__.DiscreteKalmanFilter = class DiscreteKalmanFilter {
  constructor(ad, bd, processScale, measurementScale) {
    this.ad = ad;
    this.bd = bd;
    this.h = buildMeasurementModel();
    this.state = Array(12).fill(0);
    this.covariance = scaleMatrix(identity(12), 0.8);
    this.setNoise(processScale, measurementScale);
  }

  setNoise(processScale, measurementScale) {
    this.processCov = diag([
      0.002,
      0.002,
      0.0025,
      0.018,
      0.018,
      0.02,
      0.005,
      0.005,
      0.007,
      0.03,
      0.03,
      0.036,
    ].map((value) => value * processScale));

    this.measurementCov = diag([
      0.045,
      0.045,
      0.06,
      0.018,
      0.018,
      0.022,
      0.028,
      0.028,
      0.03,
    ].map((value) => value * measurementScale));
  }

  predict(controlInput) {
    this.state = addVectorsSafe(mulMatrixVector(this.ad, this.state), mulMatrixVector(this.bd, controlInput));
    this.covariance = addMatrices(mulMatrices(this.ad, mulMatrices(this.covariance, transposeInline(this.ad))), this.processCov);
  }

  update(measurement) {
    const innovation = subVectors(measurement, mulMatrixVector(this.h, this.state));
    const s = addMatrices(mulMatrices(this.h, mulMatrices(this.covariance, transposeInline(this.h))), this.measurementCov);
    const kalmanGain = mulMatrices(this.covariance, mulMatrices(transposeInline(this.h), inverse(s)));

    this.state = addVectorsSafe(this.state, mulMatrixVector(kalmanGain, innovation));
    const identityGain = subMatrices(identity(12), mulMatrices(kalmanGain, this.h));
    this.covariance = mulMatrices(identityGain, this.covariance);
  }
}

function addVectorsSafe(a, b) {
  return a.map((value, index) => value + b[index]);
}

function transposeInline(matrix) {
  return matrix[0].map((_, col) => matrix.map((row) => row[col]));
}

// ----- quadcopter.js -----
const { buildHoverModel, buildWeights, DiscreteKalmanFilter, solveDiscreteLQR } = window.__ACL__;
const { inverse, magnitude, mulMatrixVector, subVectors } = window.__ACL__;
const { fromEuler, normalizeQuaternion, quaternionDerivative, rotateVector, toEuler } = window.__ACL__;
const DEFAULT_PARAMS = {
  mass: 1.15,
  armLength: 0.24,
  inertia: [0.018, 0.019, 0.033],
  yawCoefficient: 0.055,
  thrustLimit: 6.6,
  gravity: 9.81,
  linearDamping: 0.22,
  angularDamping: 0.19,
};

const SCENARIOS = [
  {
    name: "Recover",
    position: [-2.4, 1.4, 1.1],
    velocity: [0.2, -0.3, 0],
    euler: [0.24, -0.18, 0.28],
    omega: [0.22, -0.16, 0.12],
  },
  {
    name: "Crosswind",
    position: [1.7, -2.1, 1.8],
    velocity: [-0.6, 0.55, 0.05],
    euler: [-0.11, 0.16, -0.25],
    omega: [0.12, 0.18, -0.08],
  },
  {
    name: "Offset",
    position: [-4.2, -1.2, 0.9],
    velocity: [0.34, 0.1, 0.12],
    euler: [0.08, 0.22, 0.16],
    omega: [-0.1, 0.15, 0.16],
  },
];

const TARGETS = [
  { name: "Hover", position: [0, 0, 2.2], yaw: 0 },
  { name: "Offset", position: [3.2, -2.1, 2.6], yaw: 0.24 },
  { name: "Climb", position: [-2.6, 2.3, 3.6], yaw: -0.2 },
];

const ROUTES = [
  { name: "Off", points: [] },
  {
    name: "Box",
    points: [
      { position: [0, 0, 2.2], yaw: 0 },
      { position: [2.4, 0.6, 2.5], yaw: 0.12 },
      { position: [2.6, -2.4, 2.6], yaw: 0.25 },
      { position: [-0.4, -2.8, 2.3], yaw: -0.18 },
      { position: [0, 0, 2.2], yaw: 0 },
    ],
  },
  {
    name: "Spiral",
    points: [
      { position: [0, 0, 2.0], yaw: 0 },
      { position: [1.2, 1.0, 2.4], yaw: 0.16 },
      { position: [2.4, 0.2, 2.8], yaw: 0.3 },
      { position: [2.2, -1.8, 3.2], yaw: 0.42 },
      { position: [0.4, -2.6, 3.5], yaw: 0.56 },
      { position: [-1.8, -1.2, 3.0], yaw: 0.24 },
      { position: [0, 0, 2.2], yaw: 0 },
    ],
  },
];

window.__ACL__.QuadcopterLab = class QuadcopterLab {
  constructor() {
    this.params = { ...DEFAULT_PARAMS };
    this.sceneIndex = 0;
    this.targetIndex = 0;
    this.tuning = {
      stateWeight: 1.0,
      effortWeight: 1.0,
      processNoise: 1.0,
      measurementNoise: 1.0,
      windScale: 1.0,
    };
    this.controllerMode = "LQR";
    this.routeIndex = 0;
    this.routeTime = 0;
    this.simTime = 0;
    this.altitudeHistory = [];
    this.routeProgressHistory = [];
    this.log = [];

    this.histories = {
      error: [],
      effort: [],
      estimateGap: [],
      trueTrace: [],
      estimatedTrace: [],
    };

    this.mixMatrix = [
      [1, 1, 1, 1],
      [0, this.params.armLength, 0, -this.params.armLength],
      [-this.params.armLength, 0, this.params.armLength, 0],
      [-this.params.yawCoefficient, this.params.yawCoefficient, -this.params.yawCoefficient, this.params.yawCoefficient],
    ];
    this.mixInverse = inverse(this.mixMatrix);
    this.model = buildHoverModel(this.params, 1 / 60);
    this.controller = null;
    this.pidState = {
      positionIntegral: [0, 0, 0],
      attitudeIntegral: [0, 0, 0],
      lastPositionError: [0, 0, 0],
      lastAttitudeError: [0, 0, 0],
    };
    this.filter = null;
    this.lastCommand = [this.params.mass * this.params.gravity, 0, 0, 0];
    this.windImpulse = [0, 0, 0];
    this.motorState = [0, 0, 0, 0];
    this.setScenario(0);
    this.setTarget(0);
    this.updateTuning(this.tuning);
  }

  updateTuning(nextTuning) {
    this.tuning = { ...this.tuning, ...nextTuning };
    this.model = buildHoverModel(this.params, 1 / 60);
    const { q, r } = buildWeights(this.tuning.stateWeight, this.tuning.effortWeight);
    this.controller = solveDiscreteLQR(this.model.Ad, this.model.Bd, q, r);
    this.filter = new DiscreteKalmanFilter(this.model.Ad, this.model.Bd, this.tuning.processNoise, this.tuning.measurementNoise);
    this.filter.state = this.makeLinearStateFromTrue();
  }

  setScenario(index) {
    this.sceneIndex = (index + SCENARIOS.length) % SCENARIOS.length;
    const scenario = SCENARIOS[this.sceneIndex];
    this.trueState = {
      position: [...scenario.position],
      velocity: [...scenario.velocity],
      quaternion: fromEuler(...scenario.euler),
      omega: [...scenario.omega],
    };
    this.windImpulse = [0, 0, 0];
    this.lastCommand = [this.params.mass * this.params.gravity, 0, 0, 0];
    this.histories.error = [];
    this.histories.effort = [];
    this.histories.estimateGap = [];
    this.histories.trueTrace = [];
    this.histories.estimatedTrace = [];
    this.altitudeHistory = [];
    this.routeProgressHistory = [];
    this.log = [];
    this.pidState.positionIntegral = [0, 0, 0];
    this.pidState.attitudeIntegral = [0, 0, 0];
    this.pidState.lastPositionError = [0, 0, 0];
    this.pidState.lastAttitudeError = [0, 0, 0];
    this.motorState = [0, 0, 0, 0];
    this.routeTime = 0;
    this.simTime = 0;
    if (this.filter) {
      this.filter.state = this.makeLinearStateFromTrue();
    }
  }

  cycleScenario() {
    this.setScenario(this.sceneIndex + 1);
  }

  setTarget(index) {
    this.targetIndex = (index + TARGETS.length) % TARGETS.length;
    this.target = TARGETS[this.targetIndex];
  }

  cycleTarget() {
    this.setTarget(this.targetIndex + 1);
  }

  injectWind() {
    const strength = 4.5 * this.tuning.windScale;
    const angle = Math.random() * Math.PI * 2;
    this.windImpulse = [
      Math.cos(angle) * strength,
      Math.sin(angle) * strength,
      (Math.random() - 0.5) * 0.9 * strength,
    ];
  }

  reset() {
    this.setScenario(this.sceneIndex);
    this.setTarget(this.targetIndex);
  }

  toggleControllerMode() {
    this.controllerMode = this.controllerMode === "LQR" ? "PID" : "LQR";
  }

  cycleRoute() {
    this.routeIndex = (this.routeIndex + 1) % ROUTES.length;
    this.routeTime = 0;
    if (this.routeIndex === 0) {
      this.setTarget(this.targetIndex);
    }
  }

  step(dt) {
    this.simTime += dt;
    this.advanceRoute(dt);
    const measurement = this.makeMeasurement();
    this.filter.predict(this.lastCommand.map((value, index) => index === 0 ? value - this.params.mass * this.params.gravity : value));
    this.filter.update(measurement);

    const estimate = this.filter.state;
    const desired = [
      this.target.position[0],
      this.target.position[1],
      this.target.position[2],
      0, 0, 0,
      0, 0, this.target.yaw,
      0, 0, 0,
    ];

    const error = subVectors(estimate, desired);
    const rawCommand = this.controllerMode === "LQR"
      ? this.computeLqrCommand(error)
      : this.computePidCommand(estimate, desired, dt);
    const allocation = this.allocateMotors(rawCommand, dt);
    this.lastCommand = [allocation.totalThrust, allocation.torque[0], allocation.torque[1], allocation.torque[2]];

    this.trueState = integrateState(this.trueState, this.lastCommand, dt, this.params, this.windImpulse);
    this.windImpulse = this.windImpulse.map((value) => value * Math.pow(0.23, dt));

    const truthLinear = this.makeLinearStateFromTrue();
    const errorNorm = magnitude(subVectors(truthLinear.slice(0, 6), desired.slice(0, 6)));
    const estimateGap = magnitude(subVectors(truthLinear.slice(0, 9), estimate.slice(0, 9)));
    const effortNorm = magnitude([
      this.lastCommand[0] - this.params.mass * this.params.gravity,
      this.lastCommand[1] * 5,
      this.lastCommand[2] * 5,
      this.lastCommand[3] * 5,
    ]);

    pushHistory(this.histories.error, errorNorm);
    pushHistory(this.histories.estimateGap, estimateGap);
    pushHistory(this.histories.effort, effortNorm);
    pushTrace(this.histories.trueTrace, [...this.trueState.position]);
    pushTrace(this.histories.estimatedTrace, estimate.slice(0, 3));
    pushHistory(this.altitudeHistory, this.trueState.position[2]);
    pushHistory(this.routeProgressHistory, this.getRouteProgress());

    this.motorLevels = allocation.motors.map((value) => value / this.params.thrustLimit);
    this.metrics = {
      positionError: magnitude(subVectors(truthLinear.slice(0, 3), desired.slice(0, 3))),
      attitudeError: radToDeg(magnitude(subVectors(truthLinear.slice(6, 9), desired.slice(6, 9)))),
      windForce: magnitude(this.windImpulse),
      estimateGap,
      effortNorm,
    };
    this.log.push({
      time: Number(this.simTime.toFixed(3)),
      mode: this.controllerMode,
      route: this.routeName,
      positionError: Number(this.metrics.positionError.toFixed(4)),
      attitudeError: Number(this.metrics.attitudeError.toFixed(4)),
      estimateGap: Number(estimateGap.toFixed(4)),
      effort: Number(effortNorm.toFixed(4)),
      target: [...this.target.position],
      position: [...this.trueState.position],
    });
    if (this.log.length > 720) {
      this.log.shift();
    }
  }

  makeMeasurement() {
    const [roll, pitch, yaw] = toEuler(this.trueState.quaternion);
    const gaussian = () => {
      let u = 0;
      let v = 0;
      while (u === 0) u = Math.random();
      while (v === 0) v = Math.random();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };

    const posNoise = 0.15 * this.tuning.measurementNoise;
    const angleNoise = 0.04 * this.tuning.measurementNoise;
    const rateNoise = 0.07 * this.tuning.measurementNoise;

    return [
      this.trueState.position[0] + gaussian() * posNoise,
      this.trueState.position[1] + gaussian() * posNoise,
      this.trueState.position[2] + gaussian() * posNoise,
      roll + gaussian() * angleNoise,
      pitch + gaussian() * angleNoise,
      yaw + gaussian() * angleNoise,
      this.trueState.omega[0] + gaussian() * rateNoise,
      this.trueState.omega[1] + gaussian() * rateNoise,
      this.trueState.omega[2] + gaussian() * rateNoise,
    ];
  }

  makeLinearStateFromTrue() {
    const [roll, pitch, yaw] = toEuler(this.trueState.quaternion);
    return [
      this.trueState.position[0],
      this.trueState.position[1],
      this.trueState.position[2],
      this.trueState.velocity[0],
      this.trueState.velocity[1],
      this.trueState.velocity[2],
      roll,
      pitch,
      yaw,
      this.trueState.omega[0],
      this.trueState.omega[1],
      this.trueState.omega[2],
    ];
  }

  allocateMotors(command, dt) {
    const desiredMotors = mulMatrixVector(this.mixInverse, command).map((value) => clamp(value, 0, this.params.thrustLimit));
    const spoolRate = 1 - Math.exp(-dt / 0.18);
    this.motorState = this.motorState.map((value, index) => value + (desiredMotors[index] - value) * spoolRate);
    const totalThrust = this.motorState.reduce((sum, value) => sum + value, 0);
    const torque = [
      this.params.armLength * (this.motorState[1] - this.motorState[3]),
      this.params.armLength * (this.motorState[2] - this.motorState[0]),
      this.params.yawCoefficient * (-this.motorState[0] + this.motorState[1] - this.motorState[2] + this.motorState[3]),
    ];
    return { motors: [...this.motorState], desiredMotors, totalThrust, torque };
  }

  get sceneName() {
    return SCENARIOS[this.sceneIndex].name;
  }

  get targetName() {
    return TARGETS[this.targetIndex].name;
  }

  get routeName() {
    return ROUTES[this.routeIndex].name;
  }

  getEstimatedPose() {
    const estimate = this.filter.state;
    return {
      position: estimate.slice(0, 3),
      quaternion: fromEuler(estimate[6], estimate[7], estimate[8]),
    };
  }

  exportLog() {
    return {
      controllerMode: this.controllerMode,
      scenario: this.sceneName,
      route: this.routeName,
      target: this.targetName,
      tuning: { ...this.tuning },
      samples: [...this.log],
    };
  }

  getRouteProgress() {
    if (this.routeIndex === 0) {
      return 0;
    }
    const route = ROUTES[this.routeIndex];
    const segmentCount = Math.max(1, route.points.length - 1);
    const cycle = this.routeTime % segmentCount;
    return cycle / segmentCount;
  }

  advanceRoute(dt) {
    if (this.routeIndex === 0) {
      return;
    }

    const route = ROUTES[this.routeIndex];
    const points = route.points;
    if (points.length < 2) {
      return;
    }

    this.routeTime += dt * 0.32;
    const segmentCount = points.length - 1;
    const loopTime = this.routeTime % segmentCount;
    const segmentIndex = Math.floor(loopTime);
    const t = loopTime - segmentIndex;
    const a = points[segmentIndex];
    const b = points[(segmentIndex + 1) % points.length];

    this.target = {
      name: route.name,
      position: lerpVec(a.position, b.position, smoothstep(t)),
      yaw: a.yaw + (b.yaw - a.yaw) * smoothstep(t),
    };
  }

  computeLqrCommand(error) {
    const correction = mulMatrixVector(this.controller, error).map((value) => -value);
    return [
      this.params.mass * this.params.gravity + correction[0],
      correction[1],
      correction[2],
      correction[3],
    ];
  }

  computePidCommand(estimate, desired, dt) {
    const positionError = [
      desired[0] - estimate[0],
      desired[1] - estimate[1],
      desired[2] - estimate[2],
    ];
    const velocityError = [
      desired[3] - estimate[3],
      desired[4] - estimate[4],
      desired[5] - estimate[5],
    ];
    const attitudeError = [
      desired[6] - estimate[6],
      desired[7] - estimate[7],
      desired[8] - estimate[8],
    ];
    const rateError = [
      desired[9] - estimate[9],
      desired[10] - estimate[10],
      desired[11] - estimate[11],
    ];

    this.pidState.positionIntegral = this.pidState.positionIntegral.map((value, index) =>
      clamp(value + positionError[index] * dt, -1.2, 1.2));
    this.pidState.attitudeIntegral = this.pidState.attitudeIntegral.map((value, index) =>
      clamp(value + attitudeError[index] * dt, -0.8, 0.8));

    const kpPos = [0.85, 0.85, 2.6];
    const kdPos = [0.52, 0.52, 1.5];
    const kiPos = [0.03, 0.03, 0.28];
    const kpAtt = [0.75, 0.75, 0.44];
    const kdAtt = [0.24, 0.24, 0.18];
    const kiAtt = [0.02, 0.02, 0.02];

    const desiredPitch = clamp(
      kpPos[0] * positionError[0] + kdPos[0] * velocityError[0] + kiPos[0] * this.pidState.positionIntegral[0],
      -0.32,
      0.32,
    );
    const desiredRoll = clamp(
      -(kpPos[1] * positionError[1] + kdPos[1] * velocityError[1] + kiPos[1] * this.pidState.positionIntegral[1]),
      -0.32,
      0.32,
    );
    const thrust = this.params.mass * this.params.gravity
      + kpPos[2] * positionError[2]
      + kdPos[2] * velocityError[2]
      + kiPos[2] * this.pidState.positionIntegral[2];

    const rollError = desiredRoll - estimate[6];
    const pitchError = desiredPitch - estimate[7];
    const yawError = desired[8] - estimate[8];

    const tauX = kpAtt[0] * rollError + kdAtt[0] * rateError[0] + kiAtt[0] * this.pidState.attitudeIntegral[0];
    const tauY = kpAtt[1] * pitchError + kdAtt[1] * rateError[1] + kiAtt[1] * this.pidState.attitudeIntegral[1];
    const tauZ = kpAtt[2] * yawError + kdAtt[2] * rateError[2] + kiAtt[2] * this.pidState.attitudeIntegral[2];

    this.pidState.lastPositionError = positionError;
    this.pidState.lastAttitudeError = attitudeError;

    return [thrust, tauX, tauY, tauZ];
  }
}

function pushHistory(history, value) {
  history.push(value);
  if (history.length > 220) {
    history.shift();
  }
}

function pushTrace(history, point) {
  history.push(point);
  if (history.length > 120) {
    history.shift();
  }
}

function flattenState(state) {
  return [
    ...state.position,
    ...state.velocity,
    ...state.quaternion,
    ...state.omega,
  ];
}

function unflattenState(array) {
  return {
    position: array.slice(0, 3),
    velocity: array.slice(3, 6),
    quaternion: normalizeQuaternion(array.slice(6, 10)),
    omega: array.slice(10, 13),
  };
}

function integrateState(state, command, dt, params, windImpulse) {
  const y0 = flattenState(state);
  const k1 = stateDerivative(y0, command, params, windImpulse);
  const k2 = stateDerivative(addScaled(y0, k1, dt * 0.5), command, params, windImpulse);
  const k3 = stateDerivative(addScaled(y0, k2, dt * 0.5), command, params, windImpulse);
  const k4 = stateDerivative(addScaled(y0, k3, dt), command, params, windImpulse);

  const next = y0.map(
    (value, index) => value + (dt / 6) * (k1[index] + 2 * k2[index] + 2 * k3[index] + k4[index]),
  );
  return unflattenState(next);
}

function stateDerivative(flatState, command, params, windImpulse) {
  const state = unflattenState(flatState);
  const [qx, qy, qz] = rotateVector(state.quaternion, [0, 0, command[0]]);
  const gravity = [0, 0, -params.gravity * params.mass];
  const drag = state.velocity.map((value) => -params.linearDamping * value);
  const force = [
    qx + gravity[0] + drag[0] + windImpulse[0],
    qy + gravity[1] + drag[1] + windImpulse[1],
    qz + gravity[2] + drag[2] + windImpulse[2],
  ];

  const [ixx, iyy, izz] = params.inertia;
  const omega = state.omega;
  const inertiaOmega = [ixx * omega[0], iyy * omega[1], izz * omega[2]];
  const gyro = [
    omega[1] * inertiaOmega[2] - omega[2] * inertiaOmega[1],
    omega[2] * inertiaOmega[0] - omega[0] * inertiaOmega[2],
    omega[0] * inertiaOmega[1] - omega[1] * inertiaOmega[0],
  ];
  const torque = [
    command[1] - gyro[0] - params.angularDamping * omega[0],
    command[2] - gyro[1] - params.angularDamping * omega[1],
    command[3] - gyro[2] - params.angularDamping * omega[2],
  ];

  const acceleration = force.map((value) => value / params.mass);
  const omegaDot = [torque[0] / ixx, torque[1] / iyy, torque[2] / izz];
  const qDot = quaternionDerivative(state.quaternion, omega);

  return [
    state.velocity[0],
    state.velocity[1],
    state.velocity[2],
    acceleration[0],
    acceleration[1],
    acceleration[2],
    qDot[0],
    qDot[1],
    qDot[2],
    qDot[3],
    omegaDot[0],
    omegaDot[1],
    omegaDot[2],
  ];
}

function addScaled(vector, derivative, scale) {
  return vector.map((value, index) => value + derivative[index] * scale);
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function radToDeg(value) {
  return (value * 180) / Math.PI;
}

function lerpVec(a, b, t) {
  return a.map((value, index) => value + (b[index] - value) * t);
}

function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

// ----- renderer.js -----
const { toEuler } = window.__ACL__;
window.__ACL__.Renderer = class Renderer {
  constructor(sceneCanvas, motorCanvas, errorCanvas, effortCanvas, altitudeCanvas) {
    this.sceneCanvas = sceneCanvas;
    this.scene = sceneCanvas.getContext("2d");
    this.motorCanvas = motorCanvas;
    this.motor = motorCanvas.getContext("2d");
    this.errorCanvas = errorCanvas;
    this.error = errorCanvas.getContext("2d");
    this.effortCanvas = effortCanvas;
    this.effort = effortCanvas.getContext("2d");
    this.altitudeCanvas = altitudeCanvas;
    this.altitude = altitudeCanvas.getContext("2d");
    this.cameraAngle = 0.85;
  }

  render(sim, elapsed) {
    this.cameraAngle += 0.05 * elapsed;
    drawScene(this.scene, this.sceneCanvas, sim, this.cameraAngle);
    drawBars(this.motor, this.motorCanvas, sim.motorLevels || [0, 0, 0, 0]);
    drawLineChart(this.error, this.errorCanvas, sim.histories.error, sim.histories.estimateGap, "#7fc8ff", "#f2c879");
    drawSingleChart(this.effort, this.effortCanvas, sim.histories.effort, "#d8ad63");
    drawLineChart(this.altitude, this.altitudeCanvas, sim.altitudeHistory || [], sim.routeProgressHistory || [], "#9ed8ff", "#cda962");
  }
}

function drawScene(ctx, canvas, sim, cameraAngle) {
  const { width, height } = canvas;
  ctx.clearRect(0, 0, width, height);

  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, "rgba(10, 20, 32, 0.85)");
  gradient.addColorStop(1, "rgba(6, 13, 24, 0.98)");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);

  drawGlow(ctx, width * 0.18, height * 0.16, 220, "rgba(91, 164, 255, 0.11)");
  drawGlow(ctx, width * 0.86, height * 0.2, 170, "rgba(242, 200, 121, 0.08)");
  drawRibbon(ctx, width, height, cameraAngle);

  const projectedGrid = [];
  for (let x = -8; x <= 8; x += 1) {
    projectedGrid.push([
      project([x, -8, 0], width, height, cameraAngle),
      project([x, 8, 0], width, height, cameraAngle),
    ]);
  }
  for (let y = -8; y <= 8; y += 1) {
    projectedGrid.push([
      project([-8, y, 0], width, height, cameraAngle),
      project([8, y, 0], width, height, cameraAngle),
    ]);
  }

  ctx.strokeStyle = "rgba(112, 154, 214, 0.14)";
  ctx.lineWidth = 1;
  projectedGrid.forEach(([a, b]) => {
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  });

  drawTarget(ctx, sim.target.position, width, height, cameraAngle);
  drawTrace(ctx, sim.histories.trueTrace || [], width, height, cameraAngle, "rgba(127, 200, 255, 0.35)");
  drawTrace(ctx, sim.histories.estimatedTrace || [], width, height, cameraAngle, "rgba(242, 200, 121, 0.3)");
  drawDrone(ctx, sim.trueState, width, height, cameraAngle, false);
  drawDrone(ctx, sim.getEstimatedPose(), width, height, cameraAngle, true);
  drawTelemetryOverlay(ctx, sim, width, height);
}

function drawDrone(ctx, state, width, height, cameraAngle, ghost) {
  const center = state.position;
  const rotorLocal = [
    [0.24, 0, 0],
    [0, 0.24, 0],
    [-0.24, 0, 0],
    [0, -0.24, 0],
  ];
  const points = rotorLocal.map((point) => addVectors(center, rotateByEuler(point, toEuler(state.quaternion))));
  const center2d = project(center, width, height, cameraAngle);

  ctx.strokeStyle = ghost ? "rgba(242, 200, 121, 0.48)" : "rgba(127, 200, 255, 0.92)";
  ctx.lineWidth = ghost ? 2 : 3.2;
  ctx.beginPath();
  ctx.moveTo(project(points[0], width, height, cameraAngle).x, project(points[0], width, height, cameraAngle).y);
  ctx.lineTo(project(points[2], width, height, cameraAngle).x, project(points[2], width, height, cameraAngle).y);
  ctx.moveTo(project(points[1], width, height, cameraAngle).x, project(points[1], width, height, cameraAngle).y);
  ctx.lineTo(project(points[3], width, height, cameraAngle).x, project(points[3], width, height, cameraAngle).y);
  ctx.stroke();

  points.forEach((point, index) => {
    const rotor = project(point, width, height, cameraAngle);
    ctx.beginPath();
    ctx.strokeStyle = ghost ? "rgba(242, 200, 121, 0.32)" : "rgba(242, 200, 121, 0.9)";
    ctx.lineWidth = 2;
    ctx.arc(rotor.x, rotor.y, ghost ? 12 : 15, 0, Math.PI * 2);
    ctx.stroke();

    if (!ghost) {
      const shimmer = 0.55 + 0.45 * Math.sin(performance.now() * 0.012 + index * 1.7);
      ctx.fillStyle = `rgba(242, 200, 121, ${0.18 * shimmer})`;
      ctx.beginPath();
      ctx.arc(rotor.x, rotor.y, 20 + shimmer * 6, 0, Math.PI * 2);
      ctx.fill();
    }
  });

  ctx.fillStyle = ghost ? "rgba(242, 200, 121, 0.66)" : "#ecf5ff";
  ctx.beginPath();
  ctx.arc(center2d.x, center2d.y, ghost ? 6 : 8, 0, Math.PI * 2);
  ctx.fill();
}

function drawTarget(ctx, target, width, height, cameraAngle) {
  const point = project(target, width, height, cameraAngle);
  ctx.strokeStyle = "rgba(242, 200, 121, 0.86)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(point.x, point.y, 18, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(point.x - 24, point.y);
  ctx.lineTo(point.x + 24, point.y);
  ctx.moveTo(point.x, point.y - 24);
  ctx.lineTo(point.x, point.y + 24);
  ctx.stroke();
}

function drawTelemetryOverlay(ctx, sim, width, height) {
  const lines = [
    `Target: ${sim.targetName}`,
    `Scenario: ${sim.sceneName}`,
    `Estimated gap: ${sim.metrics.estimateGap.toFixed(2)} m`,
    `Wind: ${sim.metrics.windForce.toFixed(2)} N`,
  ];
  ctx.fillStyle = "rgba(8, 16, 26, 0.78)";
  ctx.strokeStyle = "rgba(127, 180, 242, 0.14)";
  roundRect(ctx, width - 278, height - 164, 236, 118, 18, true, true);
  ctx.fillStyle = "#edf5ff";
  ctx.font = "600 15px Inter, sans-serif";
  ctx.fillText("Flight Notes", width - 252, height - 130);
  ctx.font = "500 13px Inter, sans-serif";
  ctx.fillStyle = "rgba(180, 196, 214, 0.95)";
  lines.forEach((line, index) => ctx.fillText(line, width - 252, height - 100 + index * 22));
}

function drawTrace(ctx, trace, width, height, cameraAngle, color) {
  if (trace.length < 2) {
    return;
  }

  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath();
  trace.forEach((point, index) => {
    const projected = project(point, width, height, cameraAngle);
    if (index === 0) {
      ctx.moveTo(projected.x, projected.y);
    } else {
      ctx.lineTo(projected.x, projected.y);
    }
  });
  ctx.stroke();
}

function drawBars(ctx, canvas, values) {
  const { width, height } = canvas;
  ctx.clearRect(0, 0, width, height);
  fillPanel(ctx, width, height);
  values.forEach((value, index) => {
    const barWidth = 58;
    const gap = 20;
    const x = 34 + index * (barWidth + gap);
    const maxHeight = 58;
    const current = Math.max(0.05, Math.min(1, value));
    ctx.fillStyle = "rgba(112, 154, 214, 0.18)";
    roundRect(ctx, x, height - 26 - maxHeight, barWidth, maxHeight, 12, true, false);
    const gradient = ctx.createLinearGradient(0, height - 26, 0, height - 26 - maxHeight);
    gradient.addColorStop(0, "rgba(127, 200, 255, 0.88)");
    gradient.addColorStop(1, "rgba(242, 200, 121, 0.96)");
    ctx.fillStyle = gradient;
    roundRect(ctx, x, height - 26 - current * maxHeight, barWidth, current * maxHeight, 12, true, false);
    ctx.fillStyle = "rgba(237, 245, 255, 0.84)";
    ctx.font = "600 12px Inter, sans-serif";
    ctx.fillText(`M${index + 1}`, x + 18, height - 8);
  });
}

function drawLineChart(ctx, canvas, primary, secondary, primaryColor, secondaryColor) {
  const { width, height } = canvas;
  ctx.clearRect(0, 0, width, height);
  fillPanel(ctx, width, height);
  drawSparkline(ctx, width, height, primary, primaryColor, 0.88);
  drawSparkline(ctx, width, height, secondary, secondaryColor, 0.64);
}

function drawSingleChart(ctx, canvas, data, color) {
  const { width, height } = canvas;
  ctx.clearRect(0, 0, width, height);
  fillPanel(ctx, width, height);
  drawSparkline(ctx, width, height, data, color, 0.82);
}

function drawSparkline(ctx, width, height, data, color, alpha) {
  if (!data.length) {
    return;
  }
  const max = Math.max(...data, 1e-3);
  ctx.strokeStyle = withAlpha(color, alpha);
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  data.forEach((value, index) => {
    const x = 18 + (index / Math.max(1, data.length - 1)) * (width - 36);
    const y = height - 20 - (value / max) * (height - 36);
    if (index === 0) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  });
  ctx.stroke();
}

function fillPanel(ctx, width, height) {
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, "rgba(10, 19, 30, 0.92)");
  gradient.addColorStop(1, "rgba(7, 14, 24, 0.92)");
  ctx.fillStyle = gradient;
  roundRect(ctx, 0, 0, width, height, 18, true, false);
}

function project(point, width, height, cameraAngle) {
  const cameraDistance = 10.5;
  const elevated = 4.8;
  const cos = Math.cos(cameraAngle);
  const sin = Math.sin(cameraAngle);

  const x = point[0] * cos - point[1] * sin;
  const y = point[0] * sin + point[1] * cos;
  const z = point[2];

  const depth = cameraDistance + y;
  const scale = 520 / depth;
  return {
    x: width * 0.5 + x * scale,
    y: height * 0.72 - (z - elevated) * scale,
  };
}

function rotateByEuler(vector, euler) {
  const [roll, pitch, yaw] = euler;
  const [x, y, z] = vector;
  const cy = Math.cos(yaw);
  const sy = Math.sin(yaw);
  const cp = Math.cos(pitch);
  const sp = Math.sin(pitch);
  const cr = Math.cos(roll);
  const sr = Math.sin(roll);

  const m00 = cy * cp;
  const m01 = cy * sp * sr - sy * cr;
  const m02 = cy * sp * cr + sy * sr;
  const m10 = sy * cp;
  const m11 = sy * sp * sr + cy * cr;
  const m12 = sy * sp * cr - cy * sr;
  const m20 = -sp;
  const m21 = cp * sr;
  const m22 = cp * cr;

  return [
    m00 * x + m01 * y + m02 * z,
    m10 * x + m11 * y + m12 * z,
    m20 * x + m21 * y + m22 * z,
  ];
}

function drawGlow(ctx, x, y, radius, color) {
  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, color);
  gradient.addColorStop(1, "rgba(0, 0, 0, 0)");
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();
}

function drawRibbon(ctx, width, height, angle) {
  ctx.save();
  ctx.strokeStyle = "rgba(111, 185, 255, 0.14)";
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  for (let i = 0; i <= width; i += 18) {
    const y = 96 + Math.sin(i * 0.008 + angle * 1.8) * 22 + Math.cos(i * 0.003 + angle) * 10;
    if (i === 0) {
      ctx.moveTo(i, y);
    } else {
      ctx.lineTo(i, y);
    }
  }
  ctx.stroke();
  ctx.restore();
}

function roundRect(ctx, x, y, width, height, radius, fill, stroke) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + width, y, x + width, y + height, radius);
  ctx.arcTo(x + width, y + height, x, y + height, radius);
  ctx.arcTo(x, y + height, x, y, radius);
  ctx.arcTo(x, y, x + width, y, radius);
  ctx.closePath();
  if (fill) {
    ctx.fill();
  }
  if (stroke) {
    ctx.stroke();
  }
}

function withAlpha(hexColor, alpha) {
  if (!hexColor.startsWith("#")) {
    return hexColor;
  }
  const value = hexColor.replace("#", "");
  const bigint = Number.parseInt(value, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function addVectors(a, b) {
  return a.map((value, index) => value + b[index]);
}

// ----- app.js -----
const { QuadcopterLab } = window.__ACL__;
const { Renderer } = window.__ACL__;
const sliderDefinitions = [
  { id: "stateWeight", label: "LQR State Weight", min: 0.4, max: 2.6, step: 0.01, value: 1.0 },
  { id: "effortWeight", label: "Control Effort Weight", min: 0.45, max: 2.8, step: 0.01, value: 1.0 },
  { id: "processNoise", label: "Kalman Process Trust", min: 0.45, max: 3.0, step: 0.01, value: 1.0 },
  { id: "measurementNoise", label: "Sensor Noise Weight", min: 0.4, max: 2.8, step: 0.01, value: 1.0 },
  { id: "windScale", label: "Wind Strength", min: 0.4, max: 2.4, step: 0.01, value: 1.0 },
];

const sim = new QuadcopterLab();
const renderer = new Renderer(
  document.getElementById("sceneCanvas"),
  document.getElementById("motorCanvas"),
  document.getElementById("errorCanvas"),
  document.getElementById("effortCanvas"),
  document.getElementById("altitudeCanvas"),
);

const statusLabel = document.getElementById("statusLabel");
const statusDot = document.getElementById("statusDot");
const positionError = document.getElementById("positionError");
const attitudeError = document.getElementById("attitudeError");
const windValue = document.getElementById("windValue");
const settleValue = document.getElementById("settleValue");
const controllerValue = document.getElementById("controllerValue");
const routeValue = document.getElementById("routeValue");
const resetButton = document.getElementById("resetButton");
const gustButton = document.getElementById("gustButton");
const targetButton = document.getElementById("targetButton");
const scenarioButton = document.getElementById("scenarioButton");
const modeButton = document.getElementById("modeButton");
const routeButton = document.getElementById("routeButton");
const pauseButton = document.getElementById("pauseButton");
const exportButton = document.getElementById("exportButton");

let paused = false;

buildSliders();
wireButtons();
kickIntro();

let last = performance.now();
requestAnimationFrame(frame);

function frame(now) {
  const dt = Math.min(0.035, (now - last) / 1000 || 1 / 60);
  last = now;
  if (!paused) {
    sim.step(dt);
  }
  renderer.render(sim, dt);
  syncText();
  requestAnimationFrame(frame);
}

function buildSliders() {
  const stack = document.getElementById("sliderStack");
  sliderDefinitions.forEach((definition) => {
    const wrapper = document.createElement("label");
    wrapper.className = "slider";

    const meta = document.createElement("div");
    meta.className = "slider__meta";

    const label = document.createElement("span");
    label.className = "slider__label";
    label.textContent = definition.label;

    const value = document.createElement("span");
    value.className = "slider__value";
    value.textContent = definition.value.toFixed(2);
    value.id = `${definition.id}Value`;

    const input = document.createElement("input");
    input.type = "range";
    input.min = definition.min;
    input.max = definition.max;
    input.step = definition.step;
    input.value = definition.value;
    input.addEventListener("input", () => {
      value.textContent = Number.parseFloat(input.value).toFixed(2);
      sim.updateTuning({ [definition.id]: Number.parseFloat(input.value) });
    });

    meta.append(label, value);
    wrapper.append(meta, input);
    stack.append(wrapper);
  });
}

function wireButtons() {
  resetButton.addEventListener("click", () => sim.reset());
  gustButton.addEventListener("click", () => sim.injectWind());
  targetButton.addEventListener("click", () => {
    sim.cycleTarget();
    targetButton.textContent = `Target: ${sim.targetName}`;
  });
  scenarioButton.addEventListener("click", () => {
    sim.cycleScenario();
    scenarioButton.textContent = `Scenario: ${sim.sceneName}`;
  });
  modeButton.addEventListener("click", () => {
    sim.toggleControllerMode();
    modeButton.textContent = `Mode: ${sim.controllerMode}`;
  });
  routeButton.addEventListener("click", () => {
    sim.cycleRoute();
    routeButton.textContent = `Route: ${sim.routeName}`;
  });
  pauseButton.addEventListener("click", () => {
    paused = !paused;
    pauseButton.textContent = paused ? "Resume" : "Pause";
  });
  exportButton.addEventListener("click", exportTelemetry);
}

function syncText() {
  positionError.textContent = `${sim.metrics.positionError.toFixed(2)} m`;
  attitudeError.textContent = `${sim.metrics.attitudeError.toFixed(1)} deg`;
  windValue.textContent = `${sim.metrics.windForce.toFixed(2)} N`;
  settleValue.textContent = paused ? "Paused" : sim.metrics.positionError < 0.45 ? "Near hover" : "Recovering";
  statusLabel.textContent = paused ? "Paused" : sim.metrics.positionError < 0.45 ? "Stable hold" : "Stabilizing";
  statusDot.style.background = paused
    ? "radial-gradient(circle, #e9f5ff, #7fc8ff)"
    : sim.metrics.positionError < 0.45
      ? "radial-gradient(circle, #fff2ca, #f2c879)"
      : "radial-gradient(circle, #ffd8cb, #ff9a7a)";
  controllerValue.textContent = sim.controllerMode;
  routeValue.textContent = sim.routeName;
}

function kickIntro() {
  const intro = document.getElementById("intro");
  setTimeout(() => intro.classList.add("intro--done"), 3200);
  setTimeout(() => intro.remove(), 4100);
}

function exportTelemetry() {
  const payload = sim.exportLog();
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `aerial-control-lab-${Date.now()}.json`;
  anchor.click();
  URL.revokeObjectURL(url);
}

